# Structurizr DSL

The workspace behind this site, as its author writes it.

```structurizr
/*
 * Internet Banking System
 * The workspace a team keeps beside its code.
 */
workspace "Big Bank plc" "The software architecture of the Internet Banking System." {

    !identifiers hierarchical
    !docs docs
    !adrs decisions

    model {
        customer = person "Personal Banking Customer" "A customer of the bank, with personal bank accounts." "Customer"

        group "Big Bank plc" {
            supportStaff = person "Customer Service Staff" "Customer service staff within the bank." "Bank Staff"

            mainframe = softwareSystem "Mainframe Banking System" "Stores all of the core banking information about customers, accounts, transactions, etc." "Existing System"

            internetBanking = softwareSystem "Internet Banking System" "Allows customers to view information about their bank accounts, and make payments." {
                spa = container "Single-Page Application" "Provides all of the Internet banking functionality to customers via their web browser." "JavaScript and Angular" "Web Browser"
                api = container "API Application" "Provides Internet banking functionality via a JSON/HTTPS API." "Java and Spring MVC" {
                    signin = component "Sign In Controller" "Allows users to sign in to the Internet Banking System." "Spring MVC Rest Controller"
                    security = component "Security Component" "Provides functionality related to signing in, changing passwords, etc." "Spring Bean"
                }
                database = container "Database" "Stores user registration information, hashed authentication credentials, access logs, etc." "Oracle Database Schema" "Database"
            }
        }

        # A single-line comment, the hash way.
        customer -> internetBanking.spa "Views account balances, and makes payments using"
        internetBanking.spa -> internetBanking.api "Makes API calls to" "JSON/HTTPS"
        internetBanking.api.signin -> internetBanking.api.security "Uses"
        internetBanking.api.security -> internetBanking.database "Reads from and writes to" "SQL/TCP" {
            tags "Synchronous"
            properties {
                "structurizr.dsl.identifier" "rel1"
            }
        }
        internetBanking -> mainframe "Gets account information from, and makes payments using" "XML/HTTPS"

        live = deploymentEnvironment "Live" {
            deploymentNode "Big Bank plc" "" "Big Bank plc data center" {
                deploymentNode "bigbank-api***" "" "Ubuntu 16.04 LTS" "" 8 {
                    containerInstance internetBanking.api
                }
            }
        }
    }

    views {
        systemContext internetBanking "SystemContext" {
            include *
            autoLayout lr
            description """
                The system context diagram for the Internet Banking System.
                It spans more than one line.
            """
        }

        container internetBanking "Containers" {
            include *
            animation {
                customer
                internetBanking.spa
                internetBanking.api internetBanking.database
            }
            autoLayout
        }

        dynamic internetBanking.api "SignIn" "Summarises how the sign in feature works in the single-page application." {
            internetBanking.spa -> internetBanking.api.signin "Submits credentials to"
            internetBanking.api.signin -> internetBanking.api.security "Validates credentials using"
            autoLayout
        }

        styles {
            element "Person" {
                color #ffffff
                fontSize 22
                shape Person
            }
            element "Existing System" {
                background #999999
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            relationship "Synchronous" {
                dashed false
                routing Orthogonal
            }
        }

        theme default
    }

    configuration {
        scope softwaresystem
    }
}
```
